1	import { ClaimStruct } from "../../../contracts/typechain-types/arbitrumToEth/VeaInboxArbToEth";
2	import { JsonRpcProvider } from "@ethersproject/providers";
3	import { ethers } from "ethers";
4	import { ClaimNotFoundError } from "./errors";
5	import { getMessageStatus } from "./arbMsgExecutor";
6	import {
7	  getClaimForEpoch,
8	  getChallengerForClaim,
9	  getVerificationForClaim,
10	  getSnapshotSentForEpoch,
11	} from "./graphQueries";
12	import { defaultEmitter } from "../utils/emitter";
13	import { BotEvents } from "./botEvents";
14	import { Network } from "../consts/bridgeRoutes";
15	import { blockAtTimestamp } from "./epochHandler";
16	import { scanLogs, findFirstLog, findLatestLog } from "./logScanner";
17	
18	enum ClaimHonestState {
19	  NONE = 0,
20	  CLAIMER = 1,
21	  CHALLENGER = 2,
22	}
23	
24	export interface ClaimParams {
25	  network: Network;
26	  chainId: number;
27	  veaOutbox: any;
28	  veaOutboxProvider: JsonRpcProvider;
29	  epoch: number;
30	  epochPeriod: number;
31	  emitter: typeof defaultEmitter;
32	  fetchClaimForEpoch?: typeof getClaimForEpoch;
33	  fetchVerificationForClaim?: typeof getVerificationForClaim;
34	  fetchChallengerForClaim?: typeof getChallengerForClaim;
35	}
36	
37	/**
38	 * Block-time estimates and epoch boundaries are both approximate, so the claim
39	 * window is padded outward at both ends. Missing the block a claim was made in
40	 * is an unchallenged-fraud failure; scanning a few hundred extra blocks costs
41	 * at most one extra chunk.
42	 */
43	const CLAIM_WINDOW_PAD_BLOCKS = 256;
44	
45	const emptyClaim = (): ClaimStruct => ({
46	  stateRoot: ethers.ZeroHash,
47	  claimer: ethers.ZeroAddress,
48	  timestampClaimed: 0,
49	  timestampVerification: 0,
50	  blocknumberVerification: 0,
51	  honest: 0,
52	  challenger: ethers.ZeroAddress,
53	});
54	
55	/**
56	 * Reconstruct the claim for an epoch from the outbox's own logs.
57	 *
58	 * Both outboxes require `_epoch == block.timestamp / epochPeriod - 1` inside
59	 * `claim()`, so a claim for epoch E can only have been made during
60	 * `[(E+1)*P, (E+2)*P)`. That is a hard bound, and scanning all of it is what
61	 * closes the detection gap: anchoring at `E*P` and clamping to a fixed block
62	 * count left the tail of the window unscanned.
63	 *
64	 * Reconstruction escalates. The cheapest candidate - an unchallenged, unverified
65	 * claim - is tried against the on-chain claim hash first, and only if that fails
66	 * do we pay to scan for `Challenged` and `VerificationStarted`, which cannot
67	 * have been emitted before the claim itself existed.
68	 *
69	 * @returns The reconstructed claim, or null if the logs could not produce one
70	 */
71	const reconstructClaimFromLogs = async (
72	  { veaOutbox, veaOutboxProvider, epoch, epochPeriod, emitter }: ClaimParams,
73	  claimHash: string,
74	  headBlock: { number: number }
75	): Promise<ClaimStruct | null> => {
76	  try {
77	    const [windowStart, windowEnd] = await Promise.all([
78	      blockAtTimestamp({ provider: veaOutboxProvider, timestamp: (epoch + 1) * epochPeriod }),
79	      blockAtTimestamp({ provider: veaOutboxProvider, timestamp: (epoch + 2) * epochPeriod }),
80	    ]);
81	    const fromBlock = Math.max(windowStart - CLAIM_WINDOW_PAD_BLOCKS, 0);
82	    const toBlock = Math.min(windowEnd + CLAIM_WINDOW_PAD_BLOCKS, headBlock.number);
83	
84	    // At most one `Claimed` can exist per epoch: `claim()` requires
85	    // `claimHashes[_epoch] == 0`, so the first hit is the only hit.
86	    const claimedLog = await findFirstLog({
87	      contract: veaOutbox,
88	      filter: veaOutbox.filters.Claimed(null, epoch, null),
89	      fromBlock,
90	      toBlock,
91	    });
92	    if (!claimedLog) {
93	      // The claim hash is non-zero, so a claim provably exists but our scan did
94	      // not see it. Distinct from an RPC failure, and worth its own log line.
95	      emitter.emit(BotEvents.CLAIMED_LOG_NOT_FOUND, epoch, fromBlock, toBlock);
96	      return null;
97	    }
98	
99	    const claim = emptyClaim();
100	    claim.stateRoot = claimedLog.data;
101	    claim.claimer = `0x${claimedLog.topics[1].slice(26)}`;
102	    claim.timestampClaimed = (await veaOutboxProvider.getBlock(claimedLog.blockNumber)).timestamp;
103	
104	    const verified = verifyClaimHash({ claim, claimHash });
105	    if (verified) return verified;
106	
107	    const [challengeLogs, verificationLogs] = await Promise.all([
108	      scanLogs({
109	        contract: veaOutbox,
110	        filter: veaOutbox.filters.Challenged(epoch, null),
111	        fromBlock: claimedLog.blockNumber,
112	        toBlock: headBlock.number,
113	      }),
114	      scanLogs({
115	        contract: veaOutbox,
116	        filter: veaOutbox.filters.VerificationStarted(epoch),
117	        fromBlock: claimedLog.blockNumber,
118	        toBlock: headBlock.number,
119	      }),
120	    ]);
121	    if (verificationLogs.length > 0) {
122	      claim.blocknumberVerification = verificationLogs[0].blockNumber;
123	      claim.timestampVerification = (await veaOutboxProvider.getBlock(verificationLogs[0].blockNumber)).timestamp;
124	    }
125	    if (challengeLogs.length > 0) claim.challenger = "0x" + challengeLogs[0].topics[2].substring(26);
126	    return claim;
127	  } catch (error) {
128	    emitter.emit(BotEvents.CLAIM_LOG_SCAN_FAILED, epoch, (error as Error)?.message);
129	    return null;
130	  }
131	};
132	
133	/**
134	 * Reconstruct the claim for an epoch from the indexer.
135	 *
136	 * The result is only ever trusted after `verifyClaimHash` checks it against the
137	 * on-chain claim hash, so a wrong answer here cannot produce a wrong decision -
138	 * only an inability to act.
139	 *
140	 * @returns The reconstructed claim, or null if the indexer has no claim
141	 */
142	const reconstructClaimFromGraph = async ({
143	  chainId,
144	  veaOutbox,
145	  veaOutboxProvider,
146	  epoch,
147	  fetchClaimForEpoch = getClaimForEpoch,
148	}: ClaimParams): Promise<ClaimStruct | null> => {
149	  const claimFromGraph = await fetchClaimForEpoch(epoch, await veaOutbox.getAddress(), chainId);
150	  if (!claimFromGraph) return null;
151	
152	  const claim = emptyClaim();
153	  claim.stateRoot = claimFromGraph.stateRoot;
154	  claim.claimer = claimFromGraph.bridger;
155	  claim.timestampClaimed = claimFromGraph.timestamp;
156	  if (claimFromGraph.verification?.[0]?.startTimestamp) {
157	    claim.timestampVerification = claimFromGraph.verification[0].startTimestamp;
158	    const txReceipt = await veaOutboxProvider.getTransactionReceipt(claimFromGraph.verification[0].startTxHash);
159	    claim.blocknumberVerification = txReceipt.blockNumber;
160	  }
161	  if (claimFromGraph.challenge?.[0]) claim.challenger = claimFromGraph.challenge[0].challenger;
162	  return claim;
163	};
164	
165	/**
166	 * Fetch the claim for an epoch, reconstructing it from logs where possible and
167	 * from the indexer otherwise. Either source is only accepted once it hashes to
168	 * the outbox's own `claimHashes[epoch]`.
169	 *
170	 * @param veaOutbox VeaOutbox contract instance
171	 * @param epoch epoch number of the claim to be fetched
172	 * @returns claim type of ClaimStruct, or null if no claim was made for the epoch
173	 */
174	const getClaim = async (params: ClaimParams): Promise<ClaimStruct | null> => {
175	  const { veaOutbox, veaOutboxProvider, epoch, emitter } = params;
176	  // The claim hash and the logs it is reconstructed from must be read at the
177	  // same block. Reading the hash at the head while scanning logs only up to
178	  // finalized makes reconstruction fail whenever an event lands in between.
179	  const headBlock = await veaOutboxProvider.getBlock("finalized");
180	  const claimHash = await veaOutbox.claimHashes(epoch, { blockTag: headBlock.number });
181	  if (claimHash === ethers.ZeroHash) return null;
182	
183	  const claimFromLogs = await reconstructClaimFromLogs(params, claimHash, headBlock);
184	  const verifiedFromLogs = claimFromLogs && verifyClaimHash({ claim: claimFromLogs, claimHash });
185	  if (verifiedFromLogs) return verifiedFromLogs;
186	
187	  const claimFromGraph = await reconstructClaimFromGraph(params);
188	  // Verify that this branch is never reached for an epoch where no claim was made
189	  if (!claimFromGraph) {
190	    emitter.emit(BotEvents.NO_CLAIM_FETCHED, epoch);
191	    throw new ClaimNotFoundError(epoch);
192	  }
