1	import { getSequencerDelaySeconds, resolveSettledReadBlocks } from "./arbToEthState";
2	import { BotEvents } from "./botEvents";
3	
4	describe("arbToEthState", () => {
5	  describe("getSequencerDelaySeconds", () => {
6	    it("reads delaySeconds out of the maxTimeVariation tuple", async () => {
7	      // maxTimeVariation returns [delayBlocks, futureBlocks, delaySeconds, futureSeconds]
8	      // with named accessors, exactly as ethers decodes a multi-value return.
9	      const tuple: any = [7200, 64, 86400, 768];
10	      tuple.delayBlocks = 7200;
11	      tuple.futureBlocks = 64;
12	      tuple.delaySeconds = 86400;
13	      tuple.futureSeconds = 768;
14	      const sequencer: any = { maxTimeVariation: jest.fn(async () => tuple) };
15	
16	      const delaySeconds = await getSequencerDelaySeconds(sequencer);
17	
18	      // Coercing the whole tuple yields NaN, which silently poisons every block
19	      // range derived from it.
20	      expect(Number.isNaN(delaySeconds)).toBe(false);
21	      expect(delaySeconds).toBe(86400);
22	    });
23	  });
24	
25	  describe("resolveSettledReadBlocks", () => {
26	    const epoch = 100;
27	    const epochPeriod = 7200;
28	    const epochBoundary = (epoch + 1) * epochPeriod; // 727200
29	
30	    // Finalized sits comfortably past the boundary; latest runs ~1000s ahead of
31	    // it, mirroring the real Arbitrum finalized/latest lag.
32	    const FINALIZED_INBOX = { number: 306_763_304, timestamp: epochBoundary + 4_000 };
33	    const LATEST_INBOX = { number: 306_767_570, timestamp: epochBoundary + 5_064 };
34	    const FINALIZED_OUTBOX = { number: 9_000_000, timestamp: epochBoundary + 4_000 };
35	
36	    const makeProviders = (inboxFinalized: any = FINALIZED_INBOX) => ({
37	      inboxProvider: {
38	        getBlock: jest.fn(async (tag: any) => (tag === "finalized" ? inboxFinalized : LATEST_INBOX)),
39	      } as any,
40	      outboxProvider: {
41	        getBlock: jest.fn(async () => FINALIZED_OUTBOX),
42	      } as any,
43	    });
44	
45	    const emitted: any[][] = [];
46	    const emitter: any = { emit: (...args: any[]) => emitted.push(args) };
47	    beforeEach(() => (emitted.length = 0));
48	
49	    const healthyFinality = jest.fn(async () => [FINALIZED_INBOX, FINALIZED_OUTBOX, false, false]) as any;
50	
51	    it("pins to the finalized inbox block, never the latest one", async () => {
52	      const { inboxProvider, outboxProvider } = makeProviders();
53	
54	      const blocks = await resolveSettledReadBlocks({
55	        inboxProvider,
56	        outboxProvider,
57	        epoch,
58	        epochPeriod,
59	        emitter,
60	        fetchBlocksAndCheckFinality: healthyFinality,
61	      });
62	
63	      // getBlocksAndCheckFinality hands back the latest block in its happy path;
64	      // staking a deposit on it exposes the read to an L2 reorg.
65	      expect(blocks).toEqual({ inboxBlock: FINALIZED_INBOX.number, outboxBlock: FINALIZED_OUTBOX.number });
66	      expect(blocks!.inboxBlock).not.toBe(LATEST_INBOX.number);
67	    });
68	
69	    it("uses the blocks the finality check validated, without re-fetching them", async () => {
70	      const { inboxProvider, outboxProvider } = makeProviders();
71	
72	      const blocks = await resolveSettledReadBlocks({
73	        inboxProvider,
74	        outboxProvider,
75	        epoch,
76	        epochPeriod,
77	        emitter,
78	        fetchBlocksAndCheckFinality: healthyFinality,
79	      });
80	
81	      // Re-fetching "finalized" would pin to a block the check never saw: the head
82	      // moves between the two calls, and the fallback provider may answer from a
83	      // different endpoint entirely.
84	      expect(inboxProvider.getBlock).not.toHaveBeenCalled();
85	      expect(outboxProvider.getBlock).not.toHaveBeenCalled();
86	      expect(blocks).toEqual({ inboxBlock: FINALIZED_INBOX.number, outboxBlock: FINALIZED_OUTBOX.number });
87	    });
88	
89	    it("returns null instead of throwing when the finality check yields nothing", async () => {
90	      const { inboxProvider, outboxProvider } = makeProviders();
91	
92	      const blocks = await resolveSettledReadBlocks({
93	        inboxProvider,
94	        outboxProvider,
95	        epoch,
96	        epochPeriod,
97	        emitter,
98	        fetchBlocksAndCheckFinality: jest.fn(async () => undefined) as any,
99	      });
100	
101	      expect(blocks).toBeNull();
102	      expect(emitted.some((e) => e[0] === BotEvents.FINALITY_ISSUE)).toBe(true);
103	    });
104	
105	    it.each([
106	      ["arbitrum", [FINALIZED_INBOX, FINALIZED_OUTBOX, true, false]],
107	      ["ethereum", [FINALIZED_INBOX, FINALIZED_OUTBOX, false, true]],
108	    ])("refuses to decide while %s finality is flagged", async (_name, result) => {
109	      const { inboxProvider, outboxProvider } = makeProviders();
110	
111	      const blocks = await resolveSettledReadBlocks({
112	        inboxProvider,
113	        outboxProvider,
114	        epoch,
115	        epochPeriod,
116	        emitter,
117	        fetchBlocksAndCheckFinality: jest.fn(async () => result) as any,
118	      });
119	
120	      expect(blocks).toBeNull();
121	      expect(emitted.some((e) => e[0] === BotEvents.FINALITY_ISSUE)).toBe(true);
122	    });
