  const [inboxFinalized, l1Finalized, finalityIssueFlagArb, finalityIssueFlagEth] = finality;
  if (finalityIssueFlagArb || finalityIssueFlagEth) {
    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
    return null;
  }

  const epochBoundary = (epoch + 1) * epochPeriod;
  if (inboxFinalized.timestamp < epochBoundary) {
    emitter.emit(BotEvents.EPOCH_NOT_SETTLED, epoch, inboxFinalized.timestamp, epochBoundary);
    return null;
  }

  // The outbox contract is not necessarily on the L1/router chain used above
  // to anchor Arbitrum's finality, so its finalized block must be read
  // separately from the chain it actually lives on.
  const outboxFinalized = outboxChainProvider ? await outboxChainProvider.getBlock("finalized") : l1Finalized;

  return { inboxBlock: inboxFinalized.number, outboxBlock: outboxFinalized.number };
};

